#!/usr/bin/env python3
import json
import sys
import threading

import booster_robotics_sdk_python as b1


def result_code_to_string(code):
    if code == b1.ApiOperationResultCode.kSucceeded:
        return "SUCCEEDED"
    if code == b1.ApiOperationResultCode.kAborted:
        return "ABORTED"
    if code == b1.ApiOperationResultCode.kCanceled:
        return "CANCELED"
    if code == b1.ApiOperationResultCode.kRejected:
        return "REJECTED"
    if code == b1.ApiOperationResultCode.kTimeout:
        return "TIMEOUT"
    return "UNKNOWN"


def parse_operation_body(body):
    if not body:
        return {}
    try:
        parsed = json.loads(body)
        return parsed if isinstance(parsed, dict) else {}
    except Exception:
        return {}


def operation_body_field(data, key):
    value = data.get(key)
    if value is None:
        return "null"
    if isinstance(value, str):
        return value
    return json.dumps(value, separators=(",", ":"))


def print_operation_body(prefix, status, message, body):
    data = parse_operation_body(body)
    raw_body = body if body else "{}"
    print(
        f"{prefix}: status={status}, message={message}, "
        f"phase={operation_body_field(data, 'phase')}, "
        f"raw_body={raw_body}"
    )


def build_steps():
    return [
        (
            "wave_hand",
            b1.LocoApiId.kWaveHand,
            b1.WaveHandParameter(
                b1.HandIndex.kRightHand,
                b1.HandAction.kHandOpen,
            ).to_json_str(),
        ),
        (
            "dance",
            b1.LocoApiId.kDance,
            b1.DanceParameter(b1.DanceId.kDabbingGesture).to_json_str(),
        ),
        (
            "change_mode_prepare",
            b1.LocoApiId.kChangeMode,
            b1.ChangeModeParameter(b1.RobotMode.kPrepare).to_json_str(),
        ),
    ]


def parse_args(argv):
    if len(argv) > 3:
        raise ValueError(
            f"Usage: {argv[0]} [robot_name] [result_timeout_sec]\n"
            f"Example: {argv[0]} '' 60"
        )

    robot_name = argv[1] if len(argv) > 1 else ""
    result_timeout_sec = int(argv[2]) if len(argv) > 2 else 60
    return robot_name, result_timeout_sec


class SequenceRunner:
    def __init__(self, client, steps, result_timeout_sec):
        self.client = client
        self.steps = steps
        self.result_timeout_sec = result_timeout_sec
        self.done = threading.Event()
        self.exit_code = 0
        self.active_index = 0
        self.lock = threading.Lock()

    def start(self):
        if not self.steps:
            self.finish(0)
            return
        self.send_step(0)

    def wait(self):
        timeout = max(self.result_timeout_sec, 0) * max(len(self.steps), 1)
        if not self.done.wait(timeout):
            self.finish(5)
        return self.exit_code

    def send_step(self, index):
        name, api_id, param = self.steps[index]
        with self.lock:
            if self.done.is_set():
                return
            self.active_index = index

        def on_start(start):
            if not self.is_active(index):
                return
            if start.status != b1.kRpcStatusCodeSuccess:
                print(
                    f"[{name}] operation rejected: "
                    f"status={start.status}, message={start.message}",
                    file=sys.stderr,
                )
                self.finish(4)
                return
            print(
                f"[{name}] operation accepted: "
                f"operation_id={start.operation_id}, api_id={start.api_id}"
            )

        def on_progress(_, progress):
            if not self.is_active(index):
                return
            print_operation_body(
                f"[{name}] progress",
                progress.status,
                progress.message,
                progress.body,
            )

        def on_result(result):
            if not self.is_active(index):
                return
            print(
                f"[{name}] result callback: "
                f"code={result_code_to_string(result.code)}, "
            )
            print_operation_body(
                f"[{name}] result body",
                result.status,
                result.message,
                result.body,
            )
            if result.code != b1.ApiOperationResultCode.kSucceeded:
                print(f"Sequence failed at step: {name}", file=sys.stderr)
                self.finish(6)
                return

            next_index = index + 1
            if next_index >= len(self.steps):
                print("Async operation sequence completed.")
                self.finish(0)
                return

            self.send_step(next_index)

        print(f"[{name}] sending operation: api_id={api_id}, param={param}")
        submit = self.client.AsyncSendApiRequest(
            api_id,
            param,
            start_callback=on_start,
            progress_callback=on_progress,
            result_callback=on_result,
            start_timeout_ms=3000,
        )
        if submit.status != b1.kRpcStatusCodeSuccess:
            print(
                f"[{name}] local submit failed: "
                f"status={submit.status}, message={submit.message}",
                file=sys.stderr,
            )
            self.finish(3)

    def is_active(self, index):
        with self.lock:
            return not self.done.is_set() and self.active_index == index

    def finish(self, code):
        with self.lock:
            if self.done.is_set():
                return
            self.exit_code = code
            self.done.set()


def main():
    try:
        robot_name, result_timeout_sec = parse_args(sys.argv)
    except Exception as exc:
        print(exc, file=sys.stderr)
        return 1

    b1.ChannelFactory.Instance().Init(0)

    client = b1.B1LocoClient()
    if robot_name:
        client.InitWithName(robot_name)
    else:
        client.Init()

    print("Waiting for loco operation service...", flush=True)
    if not client.WaitForOperationService(3000, True):
        print("Loco operation service is not ready.", file=sys.stderr)
        return 2

    runner = SequenceRunner(client, build_steps(), result_timeout_sec)
    runner.start()
    return runner.wait()


if __name__ == "__main__":
    sys.exit(main())
